from collections import Counter

class Solution:
    def getLeastFrequentDigit(self, n: int) -> int:
        s = str(n)
        freq = Counter(s)

        min_f = min(freq.values())
        # Pick smallest digit among those with min_f
        cands = [int(d) for d, f in freq.items() if f == min_f]
        return min(cands)

#include <string>
#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int getLeastFrequentDigit(long long n) {
        std::string s = std::to_string(n);
        std::vector<int> freq(10, 0);
        for (char c : s) freq[c - '0']++;

        int min_f = INT_MAX;
        for (int d = 0; d < 10; ++d) {
            if (freq[d] > 0) min_f = std::min(min_f, freq[d]);
        }

        for (int d = 0; d < 10; ++d) {
            if (freq[d] == min_f) return d;
        }
        return -1;
    }
};

class Solution {
    public int getLeastFrequentDigit(long n) {
        String s = String.valueOf(n);
        int[] freq = new int[10];
        for (char c : s.toCharArray()) freq[c - '0']++;

        int minF = Integer.MAX_VALUE;
        for (int d = 0; d < 10; d++) {
            if (freq[d] > 0) minF = Math.min(minF, freq[d]);
        }

        for (int d = 0; d < 10; d++) {
            if (freq[d] == minF) return d;
        }
        return -1;
    }
}

var getLeastFrequentDigit = function(n) {
    const s = n.toString();
    const freq = new Int32Array(10);
    for (const c of s) freq[c.charCodeAt(0) - 48]++;

    let minF = Infinity;
    for (let d = 0; d < 10; d++) {
        if (freq[d] > 0 && freq[d] < minF) minF = freq[d];
    }

    for (let d = 0; d < 10; d++) {
        if (freq[d] === minF) return d;
    }
    return -1;
};
